// Generated by Cypress Author on 2026-11-02.
describe('Public action placements and booking boundaries', () => {
  it('home hero services and footer staff link → correct visible sections and login without writes', () => {
    cy.task('db:snapshot').then((before) => {
      for (const lang of ['en', 'bg']) {
        for (const width of [1440, 390]) {
          cy.viewport(width, width === 390 ? 844 : 1000);
          cy.visit(`/?lang=${lang}`);
          cy.get('a[href="#services"]').eq(1).click();
          cy.location('hash').should('eq', '#services');
          cy.get('#services').should('be.visible');
          cy.get('footer a[href="/staff/login/"]').click();
          cy.location('pathname').should('eq', '/staff/login/');
          cy.get('html').should('have.attr', 'lang', lang);
        }
      }
      cy.assertNoBusinessChange(before);
    });
  });

  it('keyboard Enter selects an available date → matching times and no database writes', () => {
    cy.get('@seed').then((seed) => {
      cy.task('db:snapshot').then((before) => {
        cy.visit(`/book/?lang=en&service=${seed.services.cut}&barber=${seed.barbers.alan}`);
        cy.intercept('GET', '/book/?*').as('keyboardDate');
        cy.window().then((win) => {
          win.__auditKeyboardEvents = [];
          for (const type of ['keydown', 'keyup', 'click']) {
            win.document.addEventListener(type, (event) => win.__auditKeyboardEvents.push({
              type, key: event.key, trusted: event.isTrusted,
              target: event.target.id || event.target.dataset.date || event.target.tagName,
            }), true);
          }
        });
        // Establish actual page focus before a native key; programmatic focus
        // alone may leave the headless browser's outer document active.
        cy.get('#date-calendar').click('topLeft');
        cy.get(`[data-date="${seed.date}"]`).focus().should('be.focused');
        cy.window().then((win) => {
          cy.writeFile('.artifacts/cypress/keyboard-before.json', {
            hasFocus: win.document.hasFocus(), active: win.document.activeElement.dataset.date,
          });
        });
        cy.press(Cypress.Keyboard.Keys.ENTER);
        cy.window().then((win) => {
          cy.writeFile('.artifacts/cypress/keyboard-after.json', {
            hasFocus: win.document.hasFocus(), active: win.document.activeElement.dataset.date,
            events: win.__auditKeyboardEvents,
          });
        });
        cy.wait('@keyboardDate').its('response.statusCode').should('eq', 200);
        cy.get('#id_date').should('have.value', seed.date);
        cy.get('[data-booking-time]').should('have.length.greaterThan', 0);
        cy.assertNoBusinessChange(before);
      });
    });
  });

  it('today, booking window and closing time → only future fitting slots are selectable', () => {
    cy.get('@seed').then((seed) => {
      cy.task('db:snapshot').then((before) => {
        cy.visit(`/book/?lang=en&service=${seed.services.cut}&barber=${seed.barbers.alan}&date=2026-11-15`);
        // Audit clock is deliberately fixed at 12:00 Sofia on 15 November.
        cy.get('[data-booking-time]').each(($time) => expect($time.text().trim() > '12:00', 'offered time is after now').to.equal(true));
        for (const date of ['2026-11-14', '2026-12-14']) {
          cy.visit(`/book/?lang=en&service=${seed.services.cut}&barber=${seed.barbers.alan}&date=${date}`);
          cy.get('[data-booking-time]').should('not.exist');
        }
        cy.visit(`/book/?lang=en&service=${seed.services.cut}&barber=${seed.barbers.alan}&date=${seed.date}`);
        cy.get('[data-booking-time]').last().should('contain', '16:30');
        cy.visit(`/book/?lang=en&service=${seed.services.cut}&barber=${seed.barbers.alan}&date=${seed.date}&time=16:45`);
        cy.get('#details').should('not.exist');
        cy.contains('This time is unavailable.').should('be.visible');
        cy.visit(`/book/?lang=en&service=${seed.services.cut}&barber=${seed.barbers.boris}&date=${seed.date}`);
        cy.location('href').then((beforeUrl) => {
          // Closed in-window dates remain keyboard-focusable for accessibility,
          // but clicking them must not change an existing valid selection.
          cy.get(`[data-date="${seed.nextDate}"]`).should('have.attr', 'aria-disabled', 'true');
          cy.get(`[data-date="${seed.nextDate}"]`).click();
          cy.get('#id_date').should('have.value', seed.date);
          cy.location('href').should('eq', beforeUrl);
        });
        cy.assertNoBusinessChange(before);
      });
    });
  });

  it('other compatible barber/service pairs → correct snapshots, trimmed phone and optional email', () => {
    cy.get('@seed').then((seed) => {
      cy.task('db:snapshot').then((before) => {
        const pairs = [
          { service: seed.services.cut, barber: seed.barbers.boris, time: '09:00', price: '20.00', duration: 30, name: 'AB' },
          { service: seed.services.beard, barber: seed.barbers.alan, time: '16:45', price: '10.00', duration: 15, name: 'Synthetic Beard Client' },
        ];
        for (const pair of pairs) {
          cy.visit(`/book/?lang=en&service=${pair.service}&barber=${pair.barber}&date=${seed.date}&time=${pair.time}`);
          cy.get('#details [name="customer_name"]').type(pair.name);
          cy.get('#details [name="phone"]').type(' 0888123456 ');
          cy.get('#details button').click();
          cy.location('pathname').should('match', /^\/book\/[a-f0-9-]+\/$/);
          cy.contains(pair.name).should('be.visible');
        }
        cy.task('db:snapshot').then((after) => {
          expect(after.appointments).to.have.length(before.appointments.length + 2);
          for (const pair of pairs) {
            expect(after.appointments.find((row) => row.customer_name === pair.name)).to.include({
              barber_id: pair.barber, service_id: pair.service, duration_minutes: pair.duration,
              price: pair.price, phone: '0888123456', email: '', cancelled_at: null,
            });
          }
          for (const key of Object.keys(before).filter((key) => key !== 'appointments')) expect(after[key], key).to.deep.equal(before[key]);
        });
      });
    });
  });
});
